use crate::economics::CostModel;
use chrono::{DateTime, Utc}; use rust_decimal::Decimal; use serde::{Deserialize, Serialize};

/// Accounting fields added after the initial schema. `None` means a legacy
/// record did not contain the evidence; callers must not infer it.
#[derive(Debug, Clone, Serialize, Deserialize)] pub struct Position { pub mint: String, #[serde(default)] pub position_id: Option<String>, #[serde(default)] pub token_mint: Option<String>, #[serde(default)] pub base_mint: Option<String>, #[serde(default)] pub entry_input_amount_atomic: Option<u64>, #[serde(default)] pub entry_output_amount_atomic: Option<u64>, #[serde(default)] pub token_decimals: Option<u8>, #[serde(default)] pub base_mint_decimals: Option<u8>, #[serde(default)] pub entry_fees_usd: Option<Decimal>, #[serde(default)] pub entry_slippage_bps: Option<u32>, #[serde(default)] pub entry_cost_model: Option<CostModel>, pub quantity: Decimal, pub entry_price_usd: Decimal, pub entry_time: DateTime<Utc>, pub entry_signature: String, pub high_water_price_usd: Decimal, pub realized_pnl_usd: Decimal, pub unrealized_pnl_usd: Decimal, pub fees_usd: Decimal, pub current_value_usd: Decimal, pub signal_id: String, pub exit_reason: Option<String> }
